create table if not exists public.game_content_exposures(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,game_code text not null,content_key text not null,topic text,mechanic text,location_id uuid references public.locations(id) on delete set null,answer_key text,correct boolean,response_ms integer,information_value numeric not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()); create index if not exists game_content_exposures_user_recent_idx on public.game_content_exposures(user_id,created_at desc); create index if not exists game_content_exposures_content_idx on public.game_content_exposures(user_id,content_key,created_at desc); alter table public.game_content_exposures enable row level security; drop policy if exists game_content_exposures_owner_read on public.game_content_exposures; create policy game_content_exposures_owner_read on public.game_content_exposures for select to authenticated using(auth.uid()=user_id); revoke insert,update,delete on public.game_content_exposures from anon,authenticated; grant select on public.game_content_exposures to authenticated; create or replace function public.record_game_content_exposure(p_game_code text,p_content_key text,p_topic text default null,p_mechanic text default null,p_location_id uuid default null,p_answer_key text default null,p_correct boolean default null,p_response_ms integer default null,p_information_value numeric default 0,p_metadata jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid(); v_id uuid; begin if v_user is null then raise exception 'Authentication required'; end if; if nullif(trim(p_game_code),'') is null or nullif(trim(p_content_key),'') is null then raise exception 'Game code and content key are required'; end if; insert into public.game_content_exposures(user_id,game_code,content_key,topic,mechanic,location_id,answer_key,correct,response_ms,information_value,metadata) values(v_user,trim(p_game_code),trim(p_content_key),nullif(trim(coalesce(p_topic,'')),''),nullif(trim(coalesce(p_mechanic,'')),''),p_location_id,nullif(trim(coalesce(p_answer_key,'')),''),p_correct,greatest(coalesce(p_response_ms,0),0),greatest(coalesce(p_information_value,0),0),coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('provenance','game_center','authoritative',false)) returning id into v_id; return v_id; end $$; revoke all on function public.record_game_content_exposure(text,text,text,text,uuid,text,boolean,integer,numeric,jsonb) from public,anon; grant execute on function public.record_game_content_exposure(text,text,text,text,uuid,text,boolean,integer,numeric,jsonb) to authenticated,service_role; create or replace function public.game_freshness_profile(p_game_code text default null,p_cooldown_days integer default 30) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('cooldown_days',greatest(1,least(coalesce(p_cooldown_days,30),180)),'recent_content_keys',coalesce(jsonb_agg(distinct e.content_key) filter(where e.content_key is not null),'[]'::jsonb),'recent_answer_keys',coalesce(jsonb_agg(distinct e.answer_key) filter(where e.answer_key is not null),'[]'::jsonb),'recent_topics',coalesce(jsonb_agg(distinct e.topic) filter(where e.topic is not null),'[]'::jsonb),'exposure_count',count(e.id)) from public.game_content_exposures e where e.user_id=auth.uid() and (p_game_code is null or e.game_code=p_game_code) and e.created_at>=now()-make_interval(days=>greatest(1,least(coalesce(p_cooldown_days,30),180))) $$; revoke all on function public.game_freshness_profile(text,integer) from public,anon; grant execute on function public.game_freshness_profile(text,integer) to authenticated,service_role;
